xml 코드를 제외한 로그 헤더를 삭제해야 함.





filter {
 mutate {
  remove_field => ["@timestamp", "@version", "path", "host"]
 }

 mutate {
  gsub => ["message", "[^<]+", ""]
  remove_field => ["@timeatamp", "@version", "path", "host"]
 }


 xml {
  force_array => false
  source => "message"
  target => "event"
 }
}




